PS_SCRIPT = r'''
# 强制 UTF-8 输出，避免中文在管道中被误读为乱码
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8
chcp 65001 | Out-Null
$ErrorActionPreference = 'SilentlyContinue'
function Log($m){ Write-Output $m }
function Find-WifiAdapter {
  $found = Get-NetAdapter | Where-Object {
    $_.MediaType -eq 'Native 802.11' -or
    $_.InterfaceDescription -match 'Wireless|Wi-?Fi|802\\.11|WLAN|无线' -or
    ($_.Name -and ($_.Name -match 'Wi-?Fi|WLAN|无线网络|无线'))
  } | Select-Object -First 1
  return $found
}
function Safe-AdapterName {
  param([string]$hint)
  if (-not ([string]::IsNullOrWhiteSpace($hint))) {
    $byName = Get-NetAdapter | Where-Object { $_.Name -eq $hint } | Select-Object -First 1
    if ($byName -and (-not ([string]::IsNullOrWhiteSpace($byName.Name)))) { return $byName.Name.Trim() }
  }
  $adp = Find-WifiAdapter
  if ($adp -and (-not ([string]::IsNullOrWhiteSpace($adp.Name)))) { return $adp.Name.Trim() }
  return $null
}
try {
  $adp = Find-WifiAdapter
  if ((-not $adp) -or ([string]::IsNullOrWhiteSpace($adp.Name))) {
    Write-Output "ERROR|未找到无线网卡，请确认无线网卡已启用并连接"
    exit 1
  }
  $an = $adp.Name.Trim()
  Log ("[1/5] 已识别无线网卡: '" + $an + "'")
  function Measure-Speed($phase){
    Log ("        " + $phase)
    $urls = @(
      'https://speed.cloudflare.com/__down?bytes=30000000',
      'https://speedtest.tele2.net/30MB.zip',
      'https://download.thinkbroadband.com/20MB.zip'
    )
    foreach ($u in $urls){
      try {
        $tmp = [System.IO.Path]::GetTempFileName()
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        Invoke-WebRequest -Uri $u -OutFile $tmp -TimeoutSec 15 -UseBasicParsing -ErrorAction Stop
        $sw.Stop()
        $b = (Get-Item $tmp).Length
        Remove-Item $tmp -Force -ErrorAction SilentlyContinue
        if ($sw.Elapsed.TotalSeconds -le 0){ continue }
        return [math]::Round(($b*8/1048576)/$sw.Elapsed.TotalSeconds,1)
      } catch { Remove-Item $tmp -Force -ErrorAction SilentlyContinue }
    }
    return $null
  }
  $naBefore = Safe-AdapterName $an
  if (-not $naBefore) { throw "无法获取优化前的网卡信息" }
  $beforeLink = (Get-NetAdapter -Name $naBefore).LinkSpeed
  $beforeSpeed = Measure-Speed '优化前测速中...'
  Log ("[2/5] 优化前连接速率: " + $beforeLink)
  Log ("[3/5] 设置首选 5GHz 频带 (强制优先连接 5G WiFi)...")
  $p = Get-NetAdapterAdvancedProperty -Name $naBefore | Where-Object { $_.DisplayName -match 'band|频带|prefer|首选' } | Select-Object -First 1
  if ($p -and $p.DisplayName){
    $pn = $p.DisplayName
    $vv = (Get-NetAdapterAdvancedProperty -Name $naBefore -DisplayName $pn).ValidDisplayValues
    $tv = $vv | Where-Object { $_ -match '5' -and ($_ -match 'GHz|赫兹|5G') } | Select-Object -First 1
    if ($tv){ Set-NetAdapterAdvancedProperty -Name $naBefore -DisplayName $pn -DisplayValue $tv -NoRestart; Log ("        已写入: " + $pn + " = " + $tv) }
    else { Log "        未找到明确的 5G 选项，已跳过" }
  } else { Log "        未找到'首选频带'属性，已跳过" }
  Log ("[4/5] 关闭网卡电源节能 (注册表 PnPCapabilities=24)...")
  $dev = Get-CimInstance Win32_NetworkAdapter | Where-Object { $_.NetConnectionID -eq $naBefore -or $_.Name -eq $naBefore } | Select-Object -First 1
  if ($dev -and $dev.PNPDeviceID){
    $rp = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($dev.PNPDeviceID)\Device Parameters"
    if (-not (Test-Path $rp)){ New-Item -Path $rp -Force | Out-Null }
    New-ItemProperty -Path $rp -Name 'PnPCapabilities' -Value 24 -PropertyType DWord -Force | Out-Null
  }
  Log ("[5/5] 重启无线网卡使设置生效...")
  # 在重启前再次确认名称非空，并捕获异常、提供降级方案
  $naRestart = Safe-AdapterName $naBefore
  if (-not $naRestart) { throw "重启前无法定位网卡名称，优化中止" }
  try {
    Restart-NetAdapter -Name $naRestart -Confirm:$false -ErrorAction Stop
  } catch {
    Log "        Restart-NetAdapter 失败，尝试禁用/启用网卡..."
    try { Disable-NetAdapter -Name $naRestart -Confirm:$false -ErrorAction Stop } catch { Log ("        禁用网卡失败: " + $_.Exception.Message) }
    Start-Sleep -Seconds 2
    try { Enable-NetAdapter -Name $naRestart -Confirm:$false -ErrorAction Stop } catch { Log ("        启用网卡失败: " + $_.Exception.Message) }
  }
  $w=0
  while($w -lt 20){
    $naNow = Safe-AdapterName $naRestart
    if (-not $naNow) { Start-Sleep -Seconds 1; $w++; continue }
    $status = (Get-NetAdapter -Name $naNow).Status
    if ($status -eq 'Up') { break }
    Start-Sleep -Seconds 1
    $w++
  }
  Start-Sleep -Seconds 3
  $naAfter = Safe-AdapterName $naRestart
  if (-not $naAfter) { throw "重启后无法重新定位网卡" }
  $afterLink = (Get-NetAdapter -Name $naAfter).LinkSpeed
  $afterSpeed = Measure-Speed '优化后测速中...'
  $bs = if($beforeSpeed){$beforeSpeed.ToString()}else{'N/A'}
  $as = if($afterSpeed){$afterSpeed.ToString()}else{'N/A'}
  $gain = if($beforeSpeed -and $afterSpeed){[math]::Round($afterSpeed-$beforeSpeed,1)}else{$null}
  $g = if($gain){$gain.ToString()}else{'N/A'}
  Write-Output ("RESULT|beforeLink=" + $beforeLink + "|afterLink=" + $afterLink + "|beforeSpeed=" + $bs + "|afterSpeed=" + $as + "|gain=" + $g)
} catch {
  $errMsg = $_.Exception.Message
  $errLine = $_.InvocationInfo.ScriptLineNumber
  Write-Output ("ERROR|" + $errMsg + " (脚本行号: " + $errLine + ")")
}
'''


def _rounded_rect(canvas, x1, y1, x2, y2, radius, **kwargs):
    """Draw a rounded rectangle on a canvas."""
    points = [
        x1 + radius, y1,
        x2 - radius, y1,
        x2, y1,
        x2, y1 + radius,
        x2, y2 - radius,
        x2, y2,
        x2 - radius, y2,
        x1 + radius, y2,
        x1, y2,
        x1, y2 - radius,
        x1, y1 + radius,
        x1, y1,
    ]
    return canvas.create_polygon(points, smooth=True, **kwargs)


class RoundedFrame(tk.Canvas):
    """A canvas-based rounded rectangle panel with optional title."""
    def __init__(self, parent, bg_color, fg_color=None, title=None, title_font=None,
                 radius=16, padx=0, pady=0, **kwargs):
        self.frame_height = kwargs.pop("height", None)
        # 显式把 height 传给 Canvas，否则圆角面板会被压成默认 7px 高
        if self.frame_height is not None:
            kwargs["height"] = self.frame_height
        super().__init__(parent, bg=kwargs.pop("bg", "#ffffff"), highlightthickness=0, **kwargs)
        self.bg_color = bg_color
        self.fg_color = fg_color or "#1f2937"
        self.radius = radius
        self.title = title
        self.title_font = title_font or ("Microsoft YaHei UI", 14, "bold")
        self.bind("<Configure>", lambda e: self._draw())
        # inner frame for child widgets
        self.inner = tk.Frame(self, bg=bg_color)
        self.inner.bind("<Configure>", lambda e: self._draw())
        self._draw()

    def _draw(self):
        self.delete("all")
        w = self.winfo_width()
        h = self.winfo_height()
        # 若尚未映射导致尺寸为 1，用显式高度兜底
        if h < 20 and self.frame_height:
            h = self.frame_height
        if w < 20 or h < 20:
            self.after(10, self._draw)
            return
        _rounded_rect(self, 0, 0, w, h, self.radius, fill=self.bg_color, outline="")
        title_h = 0
        if self.title:
            # draw title text at top-left
            self.create_text(18, 14, text=self.title, fill=self.fg_color,
                             font=self.title_font, anchor="nw")
            title_h = 26
        # place inner frame
        self.inner.place(x=16, y=10 + title_h, width=max(20, w - 32), height=max(20, h - 20 - title_h))

    def set_title(self, title):
        self.title = title
        self._draw()


class RoundedButton(tk.Canvas):
    """A rounded button with hover color animation."""
    def __init__(self, parent, text, command, bg, fg, hover_bg, font,
                 radius=20, padx=32, pady=14, **kwargs):
        super().__init__(parent, highlightthickness=0, bg=kwargs.pop("bg", "#ecfdf5"), **kwargs)
        self.text = text
        self.command = command
        self.bg = bg
        self.fg = fg
        self.hover_bg = hover_bg
        self.font = font
        self.radius = radius
        self.padx = padx
        self.pady = pady
        self._bg_current = bg
        self._rect = None
        self._txt = None
        self.bind("<Configure>", lambda e: self._draw())
        self.bind("<Enter>", self._on_enter)
        self.bind("<Leave>", self._on_leave)
        self.bind("<Button-1>", self._on_click)
        self.after(10, self._draw)

    def _draw(self):
        self.delete("all")
        w = self.winfo_width()
        h = self.winfo_height()
        if w < 20 or h < 20:
            self.after(10, self._draw)
            return
        self._rect = _rounded_rect(self, 0, 0, w, h, self.radius,
                                   fill=self._bg_current, outline="")
        self._txt = self.create_text(w // 2, h // 2, text=self.text, fill=self.fg,
                                     font=self.font, anchor="center")

    def _animate_color(self, target):
        self._bg_current = target
        self.itemconfig(self._rect, fill=target)

    def _on_enter(self, event=None):
        self._animate_color(self.hover_bg)

    def _on_leave(self, event=None):
        self._animate_color(self.bg)

    def _on_click(self, event=None):
        if self.command:
            self.command()

    def config(self, **kwargs):
        if "text" in kwargs:
            self.text = kwargs.pop("text")
        if "state" in kwargs:
            state = kwargs.pop("state")
            if state == tk.DISABLED:
                self.bind("<Enter>", lambda e: None)
                self.bind("<Leave>", lambda e: None)
                self._animate_color("#9ca3af")
            else:
                self.bind("<Enter>", self._on_enter)
                self.bind("<Leave>", self._on_leave)
                self._animate_color(self.bg)
        self._draw()


